#include <iostream>
#include <string>

struct Date {
    int d;
    int m;
    int y;
};

struct Student {
    std::string name;
    Date dob;
    int gender; // 1: Nam, 0: Nu
    float gpa;
};

int main() {
    Student x;
    if (!(std::cin >> x.name >> x.dob.d >> x.dob.m >> x.dob.y >> x.gender >> x.gpa)) {
        return 0;
    }

    // Direct structure assignment
    Student y = x;

    // Dynamic allocation and assignment through pointer
    Student* p = new Student[1];
    *p = x;

    std::cout << "Thong tin ve sinh vien y la:\n";
    std::cout << "Ho va ten: " << y.name << "\n";
    std::cout << "Sinh ngay: " << y.dob.d << "/" << y.dob.m << "/" << y.dob.y << "\n";
    std::cout << "Gioi tinh: " << (y.gender == 1 ? "Nam" : "Nu") << "\n";
    std::cout << "Diem: " << y.gpa << "\n";

    std::cout << "Pointer copy: " << p->name << " - " << p->gpa << "\n";

    delete[] p;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct Fraction {
    int num;
    int den;
};

struct Date {
    int d, m, y;
};

struct Student {
    std::string name;
    Date dob;
    int gender; // 1: Nam, 0: Nu
    float score;
};

int main() {
    // Part 1: All 4 fraction operations from source page 153
    Fraction a{1, 2};
    Fraction b{1, 3};
    Fraction c;

    c.num = a.num * b.den + a.den * b.num;
    c.den = a.den * b.den;
    std::cout << "a + b = " << c.num << "/" << c.den << "\n";

    c.num = a.num * b.den - a.den * b.num;
    c.den = a.den * b.den;
    std::cout << "a - b = " << c.num << "/" << c.den << "\n";

    c.num = a.num * b.num;
    c.den = a.den * b.den;
    std::cout << "a * b = " << c.num << "/" << c.den << "\n";

    c.num = a.num * b.den;
    c.den = a.den * b.num;
    std::cout << "a / b = " << c.num << "/" << c.den << "\n";

    // Part 2: Struct array statistics and top score search
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<Student> list(n);

    float sum_male_score = 0, sum_female_score = 0;
    int count_male = 0, count_female = 0;
    float max_score = -1.0f;

    for (int i = 0; i < n; ++i) {
        std::cin >> list[i].name >> list[i].dob.d >> list[i].dob.m >> list[i].dob.y >> list[i].gender >> list[i].score;
        if (list[i].gender == 1) {
            count_male++;
            sum_male_score += list[i].score;
        } else {
            count_female++;
            sum_female_score += list[i].score;
        }
        if (list[i].score > max_score) {
            max_score = list[i].score;
        }
    }

    if (count_male > 0)
        std::cout << "Diem tb nam: " << (sum_male_score / count_male) << "\n";
    if (count_female > 0)
        std::cout << "Diem tb nu: " << (sum_female_score / count_female) << "\n";

    std::cout << "Sinh vien diem cao nhat (" << max_score << "):\n";
    for (int i = 0; i < n; ++i) {
        if (list[i].score == max_score) {
            std::cout << list[i].name << "\n";
        }
    }

    return 0;
}
